queries.facets:
SELECT DISTINCT ?item ?itemLabel ?alias ?unii ?cas ?pubchemCid ?role ?roleLabel ?atc ?class ?classLabel WHERE {
  { VALUES ?selected { {{VALUES}} } ?item wdt:{{PROPERTY}} ?selected . ?item wdt:P652 ?unii . }
  UNION
  { VALUES ?selected { {{VALUES}} } ?item wdt:{{PROPERTY}} ?selected . ?item wdt:P231 ?cas . }
  UNION
  { VALUES ?selected { {{VALUES}} } ?item wdt:{{PROPERTY}} ?selected . ?item wdt:P662 ?pubchemCid . }
  UNION
  { VALUES ?selected { {{VALUES}} } ?item wdt:{{PROPERTY}} ?selected . ?item wdt:P2868 ?role . OPTIONAL { ?role rdfs:label ?roleLabel . FILTER(LANG(?roleLabel) = "en") } }
  UNION
  { VALUES ?selected { {{VALUES}} } ?item wdt:{{PROPERTY}} ?selected . ?item wdt:P267 ?atc . }
  UNION
  { VALUES ?selected { {{VALUES}} } ?item wdt:{{PROPERTY}} ?selected . ?item wdt:P31 ?class . OPTIONAL { ?class rdfs:label ?classLabel . FILTER(LANG(?classLabel) = "en") } }
  UNION
  { VALUES ?selected { {{VALUES}} } ?item wdt:{{PROPERTY}} ?selected . ?item rdfs:label ?itemLabel . FILTER(LANG(?itemLabel) = "en") }
  UNION
  { VALUES ?selected { {{VALUES}} } ?item wdt:{{PROPERTY}} ?selected . ?item skos:altLabel ?alias . FILTER(LANG(?alias) = "en") }
}
